# Generated by house_price_prediction.ipynb (Step 12). Run with: python app.py
import json
from pathlib import Path

import gradio as gr
import joblib
import pandas as pd
import spaces

import feature_engineering  # noqa: F401  (the saved pipeline needs add_age_features from this module)

APP_DIR = Path(__file__).parent
pipeline = joblib.load(APP_DIR / "artifacts" / "house_price_pipeline.joblib")
metadata = json.loads((APP_DIR / "artifacts" / "model_metadata.json").read_text())
ranges = metadata["input_ranges"]
test = metadata["test_metrics"]

NEIGHBORHOOD_NAMES = {
    "Blmngtn": "Bloomington Heights", "Blueste": "Bluestem", "BrDale": "Briardale",
    "BrkSide": "Brookside", "ClearCr": "Clear Creek", "CollgCr": "College Creek",
    "Crawfor": "Crawford", "Edwards": "Edwards", "Gilbert": "Gilbert",
    "IDOTRR": "Iowa DOT and Rail Road", "MeadowV": "Meadow Village", "Mitchel": "Mitchell",
    "NAmes": "North Ames", "NoRidge": "Northridge", "NPkVill": "Northpark Villa",
    "NridgHt": "Northridge Heights", "NWAmes": "Northwest Ames", "OldTown": "Old Town",
    "SWISU": "South & West of Iowa State University", "Sawyer": "Sawyer",
    "SawyerW": "Sawyer West", "Somerst": "Somerset", "StoneBr": "Stone Brook",
    "Timber": "Timberland", "Veenker": "Veenker",
}
neighborhood_choices = [(f"{NEIGHBORHOOD_NAMES.get(code, code)} ({code})", code) for code in metadata["neighborhoods"]]


@spaces.GPU(duration=10)  # required by ZeroGPU Spaces; does nothing on your laptop
def predict_price(living_area, bedrooms, full_baths, garage_cars, overall_quality,
                  neighborhood, valuation_year, year_built, year_remodeled):
    problems = []
    if living_area is None or living_area <= 0:
        problems.append("Living area must be a positive number.")
    if year_built > valuation_year:
        problems.append("Year built cannot be after the valuation year.")
    if year_remodeled < year_built:
        problems.append("Year remodeled cannot be before the year built.")
    if year_remodeled > valuation_year:
        problems.append("Year remodeled cannot be after the valuation year.")
    if problems:
        return "### Please fix these inputs\n" + "\n".join(f"- {problem}" for problem in problems)

    new_house = pd.DataFrame([{
        "GrLivArea": living_area,
        "BedroomAbvGr": bedrooms,
        "FullBath": full_baths,
        "OverallQual": overall_quality,
        "YearBuilt": year_built,
        "YearRemodAdd": year_remodeled,
        "GarageCars": garage_cars,
        "YrSold": valuation_year,
        "Neighborhood": neighborhood,
    }])[metadata["input_features"]]
    predicted_price = pipeline.predict(new_house)[0]

    message = f"## Estimated sale price: ${predicted_price:,.0f}\n"
    message += f"On held-out test homes, this model's average error was about ${test['MAE']:,.0f}."
    low, high = ranges["GrLivArea"]["min"], ranges["GrLivArea"]["max"]
    if not low <= living_area <= high:
        message += f"\n\n**Note:** living area is outside the training range ({low:,} to {high:,} sq ft), so this prediction is less reliable."
    return message


with gr.Blocks(title="House Price Predictor") as demo:
    gr.Markdown(
        "# House Price Predictor\n"
        "Estimate the sale price of a home in **Ames, Iowa**, using a model trained on historical "
        f"sales from {ranges['YrSold']['min']} to {ranges['YrSold']['max']}. "
        "This is a learning project, not a current property valuation service."
    )

    with gr.Row():
        with gr.Column():
            living_area = gr.Number(label="Above-ground living area (sq ft)", value=ranges["GrLivArea"]["median"], minimum=1, precision=0)
            bedrooms = gr.Slider(0, ranges["BedroomAbvGr"]["max"], step=1, value=ranges["BedroomAbvGr"]["median"], label="Bedrooms above ground")
            full_baths = gr.Slider(0, ranges["FullBath"]["max"], step=1, value=ranges["FullBath"]["median"], label="Full bathrooms")
            garage_cars = gr.Slider(0, ranges["GarageCars"]["max"], step=1, value=ranges["GarageCars"]["median"], label="Garage size (cars)")
            overall_quality = gr.Slider(1, 10, step=1, value=ranges["OverallQual"]["median"], label="Overall quality (1 = very poor, 10 = very excellent)")
        with gr.Column():
            neighborhood = gr.Dropdown(neighborhood_choices, value="NAmes", label="Neighborhood")
            valuation_year = gr.Dropdown(list(range(ranges["YrSold"]["min"], ranges["YrSold"]["max"] + 1)), value=ranges["YrSold"]["max"], label="Valuation year")
            year_built = gr.Number(label="Year built", value=ranges["YearBuilt"]["median"], minimum=ranges["YearBuilt"]["min"], maximum=ranges["YrSold"]["max"], precision=0)
            year_remodeled = gr.Number(
                label=f"Year remodeled (same as year built if never; earliest recorded is {ranges['YearRemodAdd']['min']})",
                value=ranges["YearRemodAdd"]["median"], minimum=ranges["YearRemodAdd"]["min"], maximum=ranges["YrSold"]["max"], precision=0,
            )

    predict_button = gr.Button("Predict price", variant="primary")
    result = gr.Markdown()
    predict_button.click(
        predict_price,
        inputs=[living_area, bedrooms, full_baths, garage_cars, overall_quality,
                neighborhood, valuation_year, year_built, year_remodeled],
        outputs=result,
    )

    with gr.Accordion("About this model", open=False):
        gr.Markdown(
            f"**Model:** {metadata['selected_model']} (scikit-learn pipeline: age features, then preprocessing, then model)\n\n"
            "**Inputs:** living area, bedrooms, full bathrooms, overall quality, year built, year remodeled, "
            "garage size, valuation year and neighborhood. The pipeline also computes *HouseAge* and "
            "*YearsSinceRemodel* from the valuation year.\n\n"
            f"**Test-set results:** MAE ${test['MAE']:,.0f} | RMSE ${test['RMSE']:,.0f} | R² {test['R2']:.3f}\n\n"
            f"**Data:** {metadata['dataset_source']}\n\n"
            "Predictions show how this model behaves on historical Ames sales. A change in prediction when you "
            "change an input is **not** a guarantee that the change would cause that price difference in reality."
        )

if __name__ == "__main__":
    demo.launch()
